"""Produce ONE self-contained HTML decision terminal, offline-capable and simulated."""
import json,sys
from pathlib import Path
import numpy as np
import pandas as pd
import plotly.graph_objects as go
from plotly.offline import get_plotlyjs
from plotly.utils import PlotlyJSONEncoder
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from scripts.omega_demo import build
from aegis.institutional import synthetic_iv_surface

cases=build()
frame=synthetic_iv_surface(spot=25000.,stress=.42)
grid=frame.pivot(index='tenor_days',columns='moneyness',values='iv_pct')
fig=go.Figure(go.Surface(x=list(grid.columns),y=list(grid.index),z=grid.values,
    colorscale=[[0,'#194055'],[.25,'#246d7c'],[.5,'#7ab8a3'],[.75,'#dfb979'],[1.,'#de685b']],
    showscale=True,colorbar=dict(title='IV %',x=1.0,len=.78,thickness=10,tickfont=dict(size=10,color='#9aa9b4')),
    hovertemplate='Moneyness %{x:.2f}<br>Tenor %{y} days<br>Implied volatility %{z:.2f}%<extra>SIMULATED</extra>'))
fig.update_layout(paper_bgcolor='#0b141b',plot_bgcolor='#0b141b',height=360,
    scene=dict(bgcolor='#0b141b',xaxis=dict(title='Strike / spot',backgroundcolor='#0b141b',color='#9aa9b4',gridcolor='#29404a'),
               yaxis=dict(title='Days to expiry',backgroundcolor='#0b141b',color='#9aa9b4',gridcolor='#29404a'),
               zaxis=dict(title='IV %',backgroundcolor='#0b141b',color='#9aa9b4',gridcolor='#29404a'),
               camera=dict(eye=dict(x=1.7,y=1.55,z=1.15))),
    font=dict(family='Arial',size=11,color='#9caeba'),margin=dict(l=5,r=5,t=0,b=0))
figure=json.dumps(fig,cls=PlotlyJSONEncoder).replace('</','<\\/')
raw=json.dumps(cases,ensure_ascii=False).replace('</','<\\/')
html=r'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>AegisSignal Ω | Evidence Intelligence</title>
<style>
:root{color-scheme:dark;--bg:#091219;--panel:#0e1a22;--panel2:#14242d;--line:#263a44;--fg:#dfe6e9;--muted:#859aa5;--red:#ed7780;--mint:#68c6ac;--amber:#e5b469;--blue:#76abc7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:12px/1.45 "Segoe UI",Arial,sans-serif;font-variant-numeric:tabular-nums}.shell{max-width:1800px;margin:auto;padding:0 22px 26px}.top{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.logobox{font-weight:750;letter-spacing:.045em;font-size:19px;color:#e6edf0}.logobox b{color:var(--mint)}.meta{font-size:11px;color:var(--muted);letter-spacing:.04em}.signal{display:inline-block;padding:5px 10px;border:1px solid #756039;color:#e9b95d;font-size:10px;font-weight:bold;letter-spacing:.08em}.crumb{padding:18px 0 14px;display:flex;align-items:flex-end;justify-content:space-between;gap:18px}.crumb h1{font-size:20px;line-height:1.2;font-weight:650;margin:0 0 5px;letter-spacing:-.025em}.crumb p{margin:0;color:var(--muted)}label{color:var(--muted);font-size:10px;letter-spacing:.08em;text-transform:uppercase}.controls{display:flex;gap:10px;align-items:center}select{min-width:210px;background:#182932;color:#e4edf1;border:1px solid #35515c;padding:9px 12px;border-radius:3px;font:12px 'Segoe UI',sans-serif}.split{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:7px}.kpi{min-height:77px;border:1px solid var(--line);background:var(--panel);padding:10px 12px}.kpi .k{color:#87a0ab;font-size:10px;letter-spacing:.09em;text-transform:uppercase}.kpi .v{font-family:Consolas,'Courier New',monospace;font-size:21px;line-height:1.4;color:#e7eff2;font-weight:600;letter-spacing:-.05em}.kpi .sub{font-size:10px;color:#6f8592}.status{padding:9px 0 17px;display:flex;justify-content:space-between;align-items:center;gap:15px}.action{border:1px solid var(--amber);color:var(--amber);padding:6px 10px;font-size:12px;font-weight:700;letter-spacing:.07em}.status .n{color:var(--muted);font-size:11px}.cols{display:grid;grid-template-columns:1.08fr .92fr;gap:12px;margin-top:10px}.panel{background:var(--panel);border:1px solid var(--line);min-width:0}.pt{padding:12px 14px;border-bottom:1px solid var(--line);font-size:12px;letter-spacing:.03em;font-weight:650;display:flex;align-items:center;justify-content:space-between}.pt span{font-weight:normal;color:var(--muted);font-size:10px}.body{padding:13px 14px}.table{width:100%;border-collapse:collapse;text-align:left;font-size:11px}.table th{color:#738b98;font-size:10px;text-transform:uppercase;letter-spacing:.04em;font-weight:500;border-bottom:1px solid #31424c;padding:8px 6px}.table td{padding:9px 6px;border-bottom:1px solid #24333c;color:#c8d5dc}.table td.num{text-align:right;font-family:Consolas,monospace}.table th.num{text-align:right}.table tr:last-child td{border-bottom:0}.warn{color:var(--amber)!important}.bad{color:var(--red)!important}.good{color:var(--mint)!important}.tag{font-size:10px;border:1px solid #526d7a;color:#9db1bc;padding:3px 6px}.stack{display:grid;grid-template-columns:1fr 1fr;gap:12px}.track{background:#1a2a32;height:6px;position:relative;overflow:hidden;border-radius:2px;margin:7px 0 13px}.track .fill{height:100%;background:#70b6ab}.metricrow{display:flex;justify-content:space-between;align-items:center;gap:10px}.v2{color:#e4ebee;font-family:Consolas,monospace;font-size:14px}.small{color:var(--muted);font-size:11px}.terminal{border:1px solid var(--line);background:#09151c;padding:12px;margin-top:10px;font-family:Consolas,monospace;font-size:11px;line-height:1.75;color:#b2c4cb}.terminal b{color:var(--mint)}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.lower{display:grid;grid-template-columns:.94fr 1.06fr;gap:12px;margin-top:12px}.note{padding:14px 0 0;color:#788c98;font-size:10px}.pill{font-family:Consolas,monospace;font-size:11px;color:var(--red)}.bar{height:7px;background:#20323b;border-radius:2px;overflow:hidden}.barfill{height:100%;background:#c97c80}.right{text-align:right}.legend{font-size:10px;color:var(--muted)}.mono{font-family:Consolas,'Courier New',monospace}.ivheader{margin:5px 0;color:var(--muted);font-size:10px}.webdata{overflow:auto;max-height:340px}@media(max-width:1200px){.split{grid-template-columns:repeat(3,1fr)}.cols,.lower{grid-template-columns:1fr}}@media(max-width:700px){.top{height:auto;min-height:58px}.meta{display:none}.shell{padding:0 12px 18px}.crumb{display:block}.controls{margin-top:15px}.split{grid-template-columns:repeat(2,1fr)}.stack,.two{grid-template-columns:1fr}.kpi .v{font-size:18px}}
</style></head><body><div class="shell">
<header class="top"><div class="logobox">AEGIS<span style="font-weight:400;color:#8197a4">SIGNAL</span> <b>Ω</b><span style="color:#687f8b;font-size:10px;font-weight:normal;letter-spacing:.12em;margin-left:14px">RISK INTELLIGENCE</span></div><div class="meta">RESEARCH / INSTITUTIONAL SIMULATION <span class="signal" style="margin-left:10px">NOT LIVE DATA</span></div></header>
<div class="crumb"><div><h1>Evidence-to-decision command center</h1><p>First-seen provenance / conflict arbitration / conditional loss / scenario exposure / no execution</p></div><div class="controls"><label for="case">Case study</label><select id="case"><option value="RELIANCE">RELIANCE · Supply disruption</option><option value="HDFCBANK">HDFCBANK · Credit allegation</option><option value="INFY">INFY · Cyber rumor</option></select></div></div>
<div class="split">
 <div class="kpi"><div class="k">Evidence support</div><div class="v" id="k-support">—</div><div class="sub">heuristic index / not probability</div></div>
 <div class="kpi"><div class="k">Contradictory support</div><div class="v" id="k-opposition">—</div><div class="sub">independent source evidence</div></div>
 <div class="kpi"><div class="k">Independent groups</div><div class="v" id="k-groups">—</div><div class="sub">after news syndication dedup</div></div>
 <div class="kpi"><div class="k">Copies filtered</div><div class="v" id="k-copies">—</div><div class="sub">repeated sources not confirmations</div></div>
 <div class="kpi"><div class="k">Conditioned loss</div><div class="v bad" id="k-loss">—</div><div class="sub">₹ crore · synthetic scenario</div></div>
 <div class="kpi"><div class="k">Exposure at risk</div><div class="v" id="k-nav">₹500 Cr</div><div class="sub">whole synthetic multi-asset book</div></div>
</div>
<div class="status"><div><span class="meta">PROPOSED RISK WORKFLOW · <span id="claim">—</span></span><div style="margin-top:5px" class="n" id="reason">Assessing independent evidence…</div></div><div class="action" id="action">—</div></div>
<div class="cols"><section class="panel"><div class="pt">01 / EVIDENCE PROVENANCE <span>Independent groups, not URLs</span></div><div class="body webdata"><table class="table"><thead><tr><th>Publisher root</th><th>Channel</th><th>Position</th><th class="num">Strength</th><th class="num">Copies</th></tr></thead><tbody id="evidence-body"></tbody></table></div><div class="body" style="border-top:1px solid var(--line)"><div class="metricrow"><span class="small">Publisher concentration</span><span class="v2" id="dominance">—</span></div><div class="track"><div class="fill" id="dominancebar"></div></div><div class="small">Removing a dominant publication group tests whether an apparent multi-source signal is fragile.</div></div></section>
<section class="panel"><div class="pt">02 / COUNTERFACTUAL EVIDENCE <span>Remove one publisher root</span></div><div class="body" id="counterfactual"></div><div class="terminal"><span style="color:#e5b469">POLICY:</span> <b id="policy">—</b><br/><span id="policy-reason">No orders are sent; verified market data and approval remain mandatory.</span></div></section></div>
<div class="lower"><section class="panel"><div class="pt">03 / CONDITIONAL PORTFOLIO IMPACT <span>INR / ₹ Crore · simulated</span></div><div class="body"><div class="stack"><div><div class="small">Scenario P&L / ₹Cr</div><div class="v2 bad" style="font-size:23px" id="portfolio-loss">—</div></div><div><div class="small">Portfolio return / conditioned</div><div class="v2 bad" style="font-size:23px" id="portfolio-percent">—</div></div></div><table class="table" style="margin-top:10px"><thead><tr><th>Asset</th><th>Instrument</th><th class="num">Before ₹Cr</th><th class="num">P&L ₹Cr</th></tr></thead><tbody id="asset-body"></tbody></table></div></section>
<section class="panel"><div class="pt">04 / VOLATILITY GEOMETRY <span>Rotatable NIFTY-like synthetic option surface</span></div><div id="iv-3d" style="width:100%;height:370px"></div><div class="ivheader" style="padding:0 13px 10px">IV smile and term structure. No observed option chain, bid/ask, expiry calendar, arbitrage-free certification or executable quote is implied.</div></section></div>
<div class="two"><section class="panel"><div class="pt">05 / RISK TRANSMISSION <span>Synthetic sector-links; not real counterparty relationships</span></div><div class="body" id="diffusion"></div></section><section class="panel"><div class="pt">06 / DATA & MODEL INTEGRITY <span>Critical limitations, disclosed at source</span></div><div class="body"><table class="table"><tbody><tr><td>Source timestamps</td><td class="right good">Event-time enforced</td></tr><tr><td>Duplicate syndication</td><td class="right good">One publisher group</td></tr><tr><td>Disputed risk event</td><td class="right good">Abstain + investigate</td></tr><tr><td>Portfolio NAV</td><td class="right good">₹500 Cr reconciled</td></tr><tr><td>Institutional risk forecasts</td><td class="right warn">UNVALIDATED</td></tr><tr><td>Trading / exchange feed</td><td class="right bad">NOT CONNECTED</td></tr><tr><td>Graph edges</td><td class="right warn">SYNTHETIC PROXY</td></tr></tbody></table></div></section></div>
<div class="note">DATA DISCLAIMER · All issuer headlines shown here are fictional fixtures and must never be presented as real disclosures. The evidence-support index is not a probability; scenario loss is not an expected return. The implied-volatility surface is simulated. Built to demonstrate technical architecture and safety properties; no live execution or performance claim.</div>
</div><script>/* PLOTLY_JS */</script><script id="modeldata" type="application/json">/* CASES_JSON */</script><script id="surfacefigure" type="application/json">/* SURFACE_JSON */</script><script>
const DATA=JSON.parse(document.getElementById('modeldata').textContent);const CASES=Object.fromEntries(DATA.cases.map(c=>[c.ticker,c]));
const num=(v,n=2)=>Number(v).toFixed(n);const cr=v=>num(v/1e7);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(id){const c=CASES[id],s=c.state,p=c.portfolio;document.getElementById('claim').textContent=c.claim_id;document.getElementById('k-support').textContent=num(s.support_index);document.getElementById('k-opposition').textContent=num(s.opposing_index);document.getElementById('k-groups').textContent=s.publishers.length;document.getElementById('k-copies').textContent=s.publishers.reduce((a,x)=>a+x.syndicated_records-1,0);document.getElementById('k-loss').textContent='−₹'+num(Math.abs(p.conditional_pnl_inr)/1e7,2)+' Cr';document.getElementById('k-nav').textContent='₹'+cr(p.nav_inr)+' Cr';document.getElementById('action').textContent=c.decision.action.replaceAll('_',' ');document.getElementById('policy').textContent=c.decision.action;document.getElementById('policy-reason').textContent=c.decision.action==='INVESTIGATE_CONFLICT'?'Material contrary evidence: do not act on the allegation.':c.decision.action==='VERIFY_SOURCE'?'Only one independent source: defer action until corroboration.':'Scenario assessment by risk manager, not authorization to trade.';
document.getElementById('reason').textContent=`${s.independent_supporters} supporting publisher roots · ${s.independent_opponents} contradictory roots · severity ${num(s.severity)}/10 · no automatic execution`;
document.getElementById('evidence-body').innerHTML=s.publishers.map(x=>`<tr><td>${esc(x.publisher_group)}</td><td>${esc(x.source)}</td><td class="${x.stance==='contradict'?'bad':x.stance==='support'?'good':''}">${esc(x.stance.toUpperCase())}</td><td class="num">${num(x.weight)}</td><td class="num">${x.syndicated_records}</td></tr>`).join('');document.getElementById('dominance').textContent=num(s.dominance*100,1)+'%';document.getElementById('dominancebar').style.width=(s.dominance*100)+'%';document.getElementById('counterfactual').innerHTML=c.adversarial.evidence_actions.map(x=>`<div class="metricrow"><span class="small">${esc(x.publisher_group)}</span><span class="v2 ${x.delta_support>0?'bad':'good'}">${x.delta_support>0?'−':'+'}${num(Math.abs(x.delta_support))}</span></div><div class="track"><div class="fill" style="width:${Math.min(100,Math.abs(x.delta_support)*100)}%;background:${x.delta_support>0?'#df8884':'#68c6ac'}"></div></div>`).join('');document.getElementById('portfolio-loss').textContent=(p.conditional_pnl_inr<0?'−':'')+'₹'+cr(Math.abs(p.conditional_pnl_inr));document.getElementById('portfolio-percent').textContent=num(p.conditional_pnl_pct)+'%';document.getElementById('asset-body').innerHTML=[...p.assets].sort((a,b)=>a.conditional_pnl-b.conditional_pnl).slice(0,10).map(a=>`<tr><td>${esc(a.asset_id)}</td><td>${esc(a.asset_type)}</td><td class="num">${cr(a.before)}</td><td class="num ${a.conditional_pnl<0?'bad':'good'}">${a.conditional_pnl>=0?'+':''}${cr(a.conditional_pnl)}</td></tr>`).join('');let max=Math.max(...c.diffusion.propagated.map(x=>x.score),0.01);document.getElementById('diffusion').innerHTML=c.diffusion.propagated.slice(0,9).map(x=>`<div class="metricrow"><span class="small" style="width:115px">${esc(x.ticker)}</span><div class="bar" style="flex:1"><div class="barfill" style="width:${100*x.score/max}%;background:${x.direct?'#ed7780':'#70aeb7'}"></div></div><span class="mono" style="color:#bbced5">${num(x.score,3)}</span></div><div style="height:9px"></div>`).join('');}
document.getElementById('case').addEventListener('change',e=>draw(e.target.value));draw('RELIANCE');const f=JSON.parse(document.getElementById('surfacefigure').textContent);const cv=document.createElement('canvas');let gl=null;try{gl=cv.getContext('webgl2')||cv.getContext('webgl')||cv.getContext('experimental-webgl')}catch(e){};if(gl){Plotly.newPlot('iv-3d',f.data,f.layout,{displayModeBar:false,responsive:true});}else{const sf=f.data[0];Plotly.newPlot('iv-3d',[{type:'heatmap',x:sf.x,y:sf.y,z:sf.z,colorscale:sf.colorscale,colorbar:{title:'IV %',thickness:10,tickfont:{color:'#a4b7c4'}}}],{paper_bgcolor:'#0b141b',plot_bgcolor:'#0b141b',font:{color:'#a4b7c4',size:11},height:365,margin:{l:64,r:28,t:34,b:50},xaxis:{title:'Strike / spot',gridcolor:'#203640'},yaxis:{title:'Days to expiry',gridcolor:'#203640'},title:{text:'IV surface / 2D fallback — WebGL unavailable',font:{size:12,color:'#b2c6d0'}}},{displayModeBar:false,responsive:true});}
</script></body></html>'''
html=html.replace('/* PLOTLY_JS */',get_plotlyjs()).replace('/* CASES_JSON */',raw).replace('/* SURFACE_JSON */',figure)
out=ROOT/'outputs'/'Omega_Decision_Terminal_Offline.html';out.parent.mkdir(exist_ok=True)
out.write_text(html,encoding='utf8')
print('built',out,round(out.stat().st_size/1024/1024,2),'MiB')
